    public static int scoreField(String field, String value) {
        int score = 0;
        for (Signal s : httpSignals()) if (s.field.equals(field) && value != null && value.contains(s.token)) score += s.weight;
        for (Signal s : dnsSignals()) if (s.field.equals(field) && value != null && value.endsWith(s.token)) score += s.weight;
        for (Signal s : tlsSignals()) if (s.field.equals(field) && value != null && value.contains(s.token)) score += s.weight;
        return score;
    }
    public static final class Signal {
        public final String id;
        public final String field;
        public final String token;
        public final int weight;
        public final String description;
        public Signal(String id, String field, String token, int weight, String description) {
            this.id = id;
            this.field = field;
            this.token = token;
            this.weight = weight;
            this.description = description;
        }
    }
